-- DE-0 immutable source review records; no accounting or VAT consumption. PostgreSQL 17 and trusted application schema.
BEGIN;
SELECT finance_assert_r1_definitions(pg_catalog.current_schema());
CREATE OR REPLACE FUNCTION finance_supply_keys(v jsonb, expected text[]) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
 SELECT jsonb_typeof(v)='object' AND
   (SELECT array_agg(k ORDER BY k COLLATE "C") FROM jsonb_object_keys(CASE WHEN jsonb_typeof(v)='object' THEN v ELSE '{}'::jsonb END) k)
   IS NOT DISTINCT FROM (SELECT array_agg(k ORDER BY k COLLATE "C") FROM unnest(expected) k)
$$;
CREATE OR REPLACE FUNCTION finance_supply_text(v jsonb, minimum integer, maximum integer) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
 SELECT jsonb_typeof(v)='string' AND length(v#>>'{}') BETWEEN minimum AND maximum
$$;
CREATE OR REPLACE FUNCTION finance_supply_id(v jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
 SELECT finance_supply_text(v,1,200) AND btrim(v#>>'{}')=v#>>'{}' AND (v#>>'{}') !~ '[[:cntrl:] ]'
$$;
CREATE OR REPLACE FUNCTION finance_supply_money(v jsonb, signed boolean DEFAULT true) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE n numeric;
BEGIN
 IF jsonb_typeof(v) IS DISTINCT FROM 'number' THEN RETURN false; END IF;
 n:=(v#>>'{}')::numeric;
 RETURN n=trunc(n) AND abs(n)<=9007199254740991 AND (signed OR n>=0);
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
CREATE OR REPLACE FUNCTION finance_supply_amount(v jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
 SELECT finance_supply_money(v->'supply') AND finance_supply_money(v->'tax') AND finance_supply_money(v->'total')
   AND (v->>'supply')::numeric+(v->>'tax')::numeric=(v->>'total')::numeric
$$;
CREATE OR REPLACE FUNCTION finance_supply_draft_valid(v jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE x jsonb; c jsonb;
BEGIN
 IF finance_supply_keys(v,ARRAY['schemaVersion','subjectId','title','reason','lines','members','allocations','claims']) IS DISTINCT FROM true
  OR v->>'schemaVersion' IS DISTINCT FROM 'de0-supply-review-v1' OR finance_supply_id(v->'subjectId') IS DISTINCT FROM true
  OR finance_supply_text(v->'title',1,200) IS DISTINCT FROM true OR finance_supply_text(v->'reason',1,2000) IS DISTINCT FROM true OR length(btrim(v->>'title'))=0 OR length(btrim(v->>'reason'))=0
  OR jsonb_typeof(v->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(v->'lines') NOT BETWEEN 1 AND 100
  OR jsonb_typeof(v->'members') IS DISTINCT FROM 'array' OR jsonb_array_length(v->'members') NOT BETWEEN 1 AND 100
  OR jsonb_typeof(v->'allocations') IS DISTINCT FROM 'array' OR jsonb_array_length(v->'allocations')>400
  OR jsonb_typeof(v->'claims') IS DISTINCT FROM 'array' OR jsonb_array_length(v->'claims')>200 THEN RETURN false; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(v->'lines') LOOP
  IF finance_supply_keys(x,ARRAY['lineId','description','dateFrom','dateTo','fulfillment','documentId','evidenceLocation','supply','tax','total']) IS DISTINCT FROM true
   OR finance_supply_id(x->'lineId') IS DISTINCT FROM true OR finance_supply_text(x->'description',1,1000) IS DISTINCT FROM true OR length(btrim(x->>'description'))=0
   OR vat_followup_date(x->>'dateFrom') IS DISTINCT FROM true OR vat_followup_date(x->>'dateTo') IS DISTINCT FROM true OR x->>'dateFrom'>x->>'dateTo'
   OR (x->>'fulfillment') NOT IN('completed','partial','advance','unknown') OR x->>'fulfillment' IS NULL
   OR (x->'documentId'<>'null'::jsonb AND finance_supply_id(x->'documentId') IS DISTINCT FROM true)
   OR finance_supply_text(x->'evidenceLocation',0,500) IS DISTINCT FROM true OR finance_supply_amount(x) IS DISTINCT FROM true THEN RETURN false; END IF;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(v->'members') LOOP
  c:=x->'correction';
  IF finance_supply_keys(x,ARRAY['memberId','kind','sourceId','correction']) IS DISTINCT FROM true
   OR finance_supply_id(x->'memberId') IS DISTINCT FROM true OR finance_supply_id(x->'sourceId') IS DISTINCT FROM true
   OR x->>'kind' NOT IN('card','hometax','tax_invoice') OR x->>'kind' IS NULL
   OR finance_supply_keys(c,ARRAY['isCorrection','reason','originalApprovalNumber','originalMemberId','referenceStatus','role','documentId','evidenceLocation']) IS DISTINCT FROM true
   OR jsonb_typeof(c->'isCorrection') IS DISTINCT FROM 'boolean' OR finance_supply_text(c->'reason',0,2000) IS DISTINCT FROM true
   OR (c->'originalApprovalNumber'<>'null'::jsonb AND finance_supply_id(c->'originalApprovalNumber') IS DISTINCT FROM true)
   OR (c->'originalMemberId'<>'null'::jsonb AND finance_supply_id(c->'originalMemberId') IS DISTINCT FROM true)
   OR c->>'referenceStatus' NOT IN('not_collected','not_provided','unresolved','declared') OR c->>'referenceStatus' IS NULL
   OR c->>'role' NOT IN('unknown','reversal','replacement','delta') OR c->>'role' IS NULL
   OR (c->'documentId'<>'null'::jsonb AND finance_supply_id(c->'documentId') IS DISTINCT FROM true)
   OR finance_supply_text(c->'evidenceLocation',0,500) IS DISTINCT FROM true
   OR (c->'originalMemberId'<>'null'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'members') m WHERE m->>'memberId'=c->>'originalMemberId')) THEN RETURN false; END IF;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(v->'allocations') LOOP
  IF finance_supply_keys(x,ARRAY['allocationId','memberId','lineId','supply','tax','total']) IS DISTINCT FROM true
   OR finance_supply_id(x->'allocationId') IS DISTINCT FROM true OR finance_supply_id(x->'memberId') IS DISTINCT FROM true OR finance_supply_id(x->'lineId') IS DISTINCT FROM true
   OR finance_supply_amount(x) IS DISTINCT FROM true
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'members') m WHERE m->>'memberId'=x->>'memberId')
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'lines') l WHERE l->>'lineId'=x->>'lineId') THEN RETURN false; END IF;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(v->'claims') LOOP
  c:=x->'cReference';
  IF finance_supply_keys(x,ARRAY['claimId','lineId','memberId','origin','reference','claimedSupply','claimedTax','coverage','documentId','evidenceLocation','cReference']) IS DISTINCT FROM true
   OR finance_supply_id(x->'claimId') IS DISTINCT FROM true OR finance_supply_id(x->'lineId') IS DISTINCT FROM true OR finance_supply_id(x->'memberId') IS DISTINCT FROM true
   OR x->>'origin' NOT IN('external','c_consumption') OR x->>'origin' IS NULL
   OR finance_supply_text(x->'reference',0,1000) IS DISTINCT FROM true OR finance_supply_money(x->'claimedSupply',false) IS DISTINCT FROM true OR finance_supply_money(x->'claimedTax',false) IS DISTINCT FROM true
   OR x->>'coverage' NOT IN('exact','partial','unknown') OR x->>'coverage' IS NULL
   OR (x->'documentId'<>'null'::jsonb AND finance_supply_id(x->'documentId') IS DISTINCT FROM true)
   OR finance_supply_text(x->'evidenceLocation',0,500) IS DISTINCT FROM true
   OR (x->>'origin'='external' AND c<>'null'::jsonb)
   OR (c<>'null'::jsonb AND (finance_supply_keys(c,ARRAY['revisionId','pairLineNo']) IS DISTINCT FROM true OR finance_supply_id(c->'revisionId') IS DISTINCT FROM true OR finance_supply_money(c->'pairLineNo',false) IS DISTINCT FROM true OR (c->>'pairLineNo')::numeric>99))
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'members') m WHERE m->>'memberId'=x->>'memberId')
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'lines') l WHERE l->>'lineId'=x->>'lineId') THEN RETURN false; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v->'lines') item GROUP BY item->>'lineId' HAVING count(*)>1)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'members') item GROUP BY item->>'memberId' HAVING count(*)>1)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'allocations') item GROUP BY item->>'allocationId' HAVING count(*)>1)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'claims') item GROUP BY item->>'claimId' HAVING count(*)>1) THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION finance_supply_assessment_valid(draft jsonb, a jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE totals jsonb; claims jsonb;
BEGIN
 IF finance_supply_keys(a,ARRAY['schemaVersion','status','canApply','consumptionSupported','issues','lineTotals','claimedTotals','memberTotals','additionalVatDeduction']) IS DISTINCT FROM true
  OR a->>'schemaVersion' IS DISTINCT FROM 'de0-supply-assessment-v1' OR a->>'status' IS NULL OR a->>'status' NOT IN('reviewable','needs_information')
  OR a->'canApply' IS DISTINCT FROM 'false'::jsonb OR a->'consumptionSupported' IS DISTINCT FROM 'false'::jsonb OR a->'additionalVatDeduction' IS DISTINCT FROM 'null'::jsonb
  OR jsonb_typeof(a->'issues') IS DISTINCT FROM 'array' OR jsonb_typeof(a->'memberTotals') IS DISTINCT FROM 'array'
  OR finance_supply_keys(a->'lineTotals',ARRAY['supply','tax','total']) IS DISTINCT FROM true OR finance_supply_amount(a->'lineTotals') IS DISTINCT FROM true
  OR finance_supply_keys(a->'claimedTotals',ARRAY['supply','tax']) IS DISTINCT FROM true OR finance_supply_money(a->'claimedTotals'->'supply',false) IS DISTINCT FROM true OR finance_supply_money(a->'claimedTotals'->'tax',false) IS DISTINCT FROM true THEN RETURN false; END IF;
 SELECT jsonb_build_object('supply',COALESCE(sum((x->>'supply')::numeric),0),'tax',COALESCE(sum((x->>'tax')::numeric),0),'total',COALESCE(sum((x->>'total')::numeric),0)) INTO totals FROM jsonb_array_elements(draft->'lines') x;
 SELECT jsonb_build_object('supply',COALESCE(sum((x->>'claimedSupply')::numeric),0),'tax',COALESCE(sum((x->>'claimedTax')::numeric),0)) INTO claims FROM jsonb_array_elements(draft->'claims') x;
 RETURN a->'lineTotals'=totals AND a->'claimedTotals'=claims;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE TABLE IF NOT EXISTS finance_supply_review_cases (
 case_id text PRIMARY KEY CHECK(finance_supply_id(to_jsonb(case_id))),
 subject_id text NOT NULL REFERENCES vat_filing_subjects(subject_id),
 created_by text NOT NULL CHECK(finance_supply_id(to_jsonb(created_by))),
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS finance_supply_review_requests (
 request_id text PRIMARY KEY CHECK(finance_supply_id(to_jsonb(request_id))),
 action text NOT NULL CHECK(action IN('save','withdraw')),
 actor_user_id text NOT NULL CHECK(finance_supply_id(to_jsonb(actor_user_id))),
 payload_hash text NOT NULL CHECK(payload_hash ~ '^[a-f0-9]{64}$'),
 result_json jsonb NOT NULL CHECK(jsonb_typeof(result_json)='object'),
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS finance_supply_review_revisions (
 revision_id text PRIMARY KEY CHECK(finance_supply_id(to_jsonb(revision_id))),
 case_id text NOT NULL REFERENCES finance_supply_review_cases(case_id),
 version integer NOT NULL CHECK(version>0),
 previous_revision_id text UNIQUE REFERENCES finance_supply_review_revisions(revision_id),
 schema_version text NOT NULL CHECK(schema_version='de0-supply-review-v1'),
 state text NOT NULL CHECK(state IN('recorded','withdrawn')),
 payload_json jsonb NOT NULL CHECK(finance_supply_draft_valid(payload_json)),
 payload_hash text NOT NULL CHECK(payload_hash ~ '^[a-f0-9]{64}$' AND payload_hash=vat_followup_hash_v2(payload_json)),
 basis_json jsonb NOT NULL CHECK((finance_supply_keys(basis_json,ARRAY['schemaVersion','subjectId','subjectSnapshotText','subjectSnapshotHash','subjectIssues','sources','documents','cReferences']) AND basis_json->>'schemaVersion'='de0-supply-basis-v1'
  AND finance_supply_id(basis_json->'subjectId') AND jsonb_typeof(basis_json->'subjectSnapshotText')='string' AND (basis_json->>'subjectSnapshotHash') ~ '^[a-f0-9]{64}$'
  AND jsonb_typeof(basis_json->'subjectIssues')='array' AND jsonb_typeof(basis_json->'sources')='array' AND jsonb_typeof(basis_json->'documents')='array' AND jsonb_typeof(basis_json->'cReferences')='array') IS TRUE),
 basis_hash text NOT NULL CHECK(basis_hash ~ '^[a-f0-9]{64}$' AND basis_hash=vat_followup_hash_v2(basis_json)),
 assessment_json jsonb NOT NULL CHECK(finance_supply_assessment_valid(payload_json,assessment_json)),
 preview_hash text NOT NULL CHECK(preview_hash ~ '^[a-f0-9]{64}$' AND preview_hash=vat_followup_hash_v2(jsonb_build_object('draft',payload_json,'basis',basis_json,'assessment',assessment_json))),
 withdrawal_reason text,
 actor_user_id text NOT NULL CHECK(finance_supply_id(to_jsonb(actor_user_id))),
 request_id text NOT NULL UNIQUE REFERENCES finance_supply_review_requests(request_id) DEFERRABLE INITIALLY DEFERRED,
 created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(case_id,version), UNIQUE(revision_id,case_id),
 CHECK((version=1)=(previous_revision_id IS NULL)),
 CHECK((state='recorded' AND withdrawal_reason IS NULL) OR (state='withdrawn' AND withdrawal_reason IS NOT NULL AND length(btrim(withdrawal_reason)) BETWEEN 1 AND 2000))
);
CREATE INDEX IF NOT EXISTS finance_supply_review_subject_idx ON finance_supply_review_cases(subject_id,created_at,case_id);

CREATE OR REPLACE FUNCTION finance_supply_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'DE-0 review history is immutable: %',TG_TABLE_NAME USING ERRCODE='23514'; END $$;
CREATE OR REPLACE FUNCTION finance_supply_revision_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE root finance_supply_review_cases%ROWTYPE; previous finance_supply_review_revisions%ROWTYPE;
BEGIN
 PERFORM pg_advisory_xact_lock(1296256326,1);
 SELECT * INTO STRICT root FROM finance_supply_review_cases WHERE case_id=NEW.case_id FOR UPDATE;
 SELECT * INTO previous FROM finance_supply_review_revisions WHERE case_id=NEW.case_id ORDER BY version DESC LIMIT 1;
 IF NEW.version<>COALESCE(previous.version,0)+1 OR NEW.previous_revision_id IS DISTINCT FROM previous.revision_id
  OR NEW.payload_json->>'subjectId' IS DISTINCT FROM root.subject_id OR NEW.basis_json->>'subjectId' IS DISTINCT FROM root.subject_id
  OR (previous.revision_id IS NULL AND (NEW.state<>'recorded' OR NEW.actor_user_id<>root.created_by)) THEN
  RAISE EXCEPTION 'DE-0 review chain/subject/creator conflict' USING ERRCODE='23514'; END IF;
 IF NEW.state='withdrawn' AND (previous.state IS DISTINCT FROM 'recorded' OR NEW.payload_json IS DISTINCT FROM previous.payload_json
  OR NEW.basis_json IS DISTINCT FROM previous.basis_json OR NEW.assessment_json IS DISTINCT FROM previous.assessment_json
  OR NEW.preview_hash IS DISTINCT FROM previous.preview_hash) THEN
  RAISE EXCEPTION 'DE-0 withdrawal must preserve the preceding recorded basis' USING ERRCODE='23514'; END IF;
 RETURN NEW;
EXCEPTION WHEN NO_DATA_FOUND THEN RAISE EXCEPTION 'DE-0 case not found' USING ERRCODE='23514';
END $$;
CREATE OR REPLACE FUNCTION finance_supply_assert_agreement(p_case text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE root finance_supply_review_cases%ROWTYPE; r finance_supply_review_revisions%ROWTYPE; q finance_supply_review_requests%ROWTYPE;
BEGIN
 SELECT * INTO root FROM finance_supply_review_cases WHERE case_id=p_case;
 IF root.case_id IS NULL OR NOT EXISTS(SELECT 1 FROM finance_supply_review_revisions WHERE case_id=p_case AND version=1) THEN
  RAISE EXCEPTION 'DE-0 orphan case' USING ERRCODE='23514'; END IF;
 FOR r IN SELECT * FROM finance_supply_review_revisions WHERE case_id=p_case LOOP
  SELECT * INTO q FROM finance_supply_review_requests WHERE request_id=r.request_id;
  IF q.request_id IS NULL OR q.actor_user_id<>r.actor_user_id OR q.action<>(CASE r.state WHEN 'recorded' THEN 'save' ELSE 'withdraw' END)
   OR q.result_json->>'caseId' IS DISTINCT FROM r.case_id OR q.result_json->>'revisionId' IS DISTINCT FROM r.revision_id
   OR q.result_json->'version' IS DISTINCT FROM to_jsonb(r.version) OR q.result_json->>'state' IS DISTINCT FROM r.state THEN
   RAISE EXCEPTION 'DE-0 revision/request agreement failure' USING ERRCODE='23514'; END IF;
 END LOOP;
END $$;
CREATE OR REPLACE FUNCTION finance_supply_row_agreement() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE key text;
BEGIN
 IF TG_TABLE_NAME='finance_supply_review_requests' THEN
  SELECT case_id INTO key FROM finance_supply_review_revisions WHERE request_id=NEW.request_id;
  IF key IS NULL THEN RAISE EXCEPTION 'DE-0 orphan request' USING ERRCODE='23514'; END IF;
 ELSE key:=NEW.case_id; END IF;
 PERFORM finance_supply_assert_agreement(key);
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS finance_supply_revision_insert ON finance_supply_review_revisions;
CREATE TRIGGER finance_supply_revision_insert BEFORE INSERT ON finance_supply_review_revisions FOR EACH ROW EXECUTE FUNCTION finance_supply_revision_guard();
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['finance_supply_review_cases','finance_supply_review_revisions','finance_supply_review_requests'] LOOP
  EXECUTE format('DROP TRIGGER IF EXISTS finance_supply_immutable ON %I',t);
  EXECUTE format('CREATE TRIGGER finance_supply_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION finance_supply_immutable()',t);
  EXECUTE format('DROP TRIGGER IF EXISTS finance_supply_no_truncate ON %I',t);
  EXECUTE format('CREATE TRIGGER finance_supply_no_truncate BEFORE TRUNCATE ON %I FOR EACH STATEMENT EXECUTE FUNCTION finance_supply_immutable()',t);
  EXECUTE format('DROP TRIGGER IF EXISTS finance_supply_agreement ON %I',t);
  EXECUTE format('CREATE CONSTRAINT TRIGGER finance_supply_agreement AFTER INSERT ON %I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION finance_supply_row_agreement()',t);
 END LOOP;
END $$;

CREATE OR REPLACE FUNCTION finance_assert_supply_definitions(p_schema text) RETURNS jsonb LANGUAGE plpgsql AS $de0$
DECLARE expected jsonb := '{"version":"de0-supply-installation-v1","postgresMajor":17,"functions":[{"cost":"100","kind":"f","name":"finance_supply_amount","rows":"0","binary":null,"config":null,"result":"boolean","source":"\n SELECT finance_supply_money(v->''supply'') AND finance_supply_money(v->''tax'') AND finance_supply_money(v->''total'')\n   AND (v->>''supply'')::numeric+(v->>''tax'')::numeric=(v->>''total'')::numeric\n","strict":false,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"v jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_supply_assert_agreement","rows":"0","binary":null,"config":null,"result":"void","source":"\nDECLARE root finance_supply_review_cases%ROWTYPE; r finance_supply_review_revisions%ROWTYPE; q finance_supply_review_requests%ROWTYPE;\nBEGIN\n SELECT * INTO root FROM finance_supply_review_cases WHERE case_id=p_case;\n IF root.case_id IS NULL OR NOT EXISTS(SELECT 1 FROM finance_supply_review_revisions WHERE case_id=p_case AND version=1) THEN\n  RAISE EXCEPTION ''DE-0 orphan case'' USING ERRCODE=''23514''; END IF;\n FOR r IN SELECT * FROM finance_supply_review_revisions WHERE case_id=p_case LOOP\n  SELECT * INTO q FROM finance_supply_review_requests WHERE request_id=r.request_id;\n  IF q.request_id IS NULL OR q.actor_user_id<>r.actor_user_id OR q.action<>(CASE r.state WHEN ''recorded'' THEN ''save'' ELSE ''withdraw'' END)\n   OR q.result_json->>''caseId'' IS DISTINCT FROM r.case_id OR q.result_json->>''revisionId'' IS DISTINCT FROM r.revision_id\n   OR q.result_json->''version'' IS DISTINCT FROM to_jsonb(r.version) OR q.result_json->>''state'' IS DISTINCT FROM r.state THEN\n   RAISE EXCEPTION ''DE-0 revision/request agreement failure'' USING ERRCODE=''23514''; END IF;\n END LOOP;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_c