T 1;\n IF NEW.version<>COALESCE(previous.version,0)+1 OR NEW.previous_revision_id IS DISTINCT FROM previous.revision_id\n  OR NEW.payload_json->>''subjectId'' IS DISTINCT FROM root.subject_id OR NEW.basis_json->>''subjectId'' IS DISTINCT FROM root.subject_id\n  OR (previous.revision_id IS NULL AND (NEW.state<>''recorded'' OR NEW.actor_user_id<>root.created_by)) THEN\n  RAISE EXCEPTION ''DE-0 review chain/subject/creator conflict'' USING ERRCODE=''23514''; END IF;\n IF NEW.state=''withdrawn'' AND (previous.state IS DISTINCT FROM ''recorded'' OR NEW.payload_json IS DISTINCT FROM previous.payload_json\n  OR NEW.basis_json IS DISTINCT FROM previous.basis_json OR NEW.assessment_json IS DISTINCT FROM previous.assessment_json\n  OR NEW.preview_hash IS DISTINCT FROM previous.preview_hash) THEN\n  RAISE EXCEPTION ''DE-0 withdrawal must preserve the preceding recorded basis'' USING ERRCODE=''23514''; END IF;\n RETURN NEW;\nEXCEPTION WHEN NO_DATA_FOUND THEN RAISE EXCEPTION ''DE-0 case not found'' USING ERRCODE=''23514'';\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_supply_row_agreement","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE key text;\nBEGIN\n IF TG_TABLE_NAME=''finance_supply_review_requests'' THEN\n  SELECT case_id INTO key FROM finance_supply_review_revisions WHERE request_id=NEW.request_id;\n  IF key IS NULL THEN RAISE EXCEPTION ''DE-0 orphan request'' USING ERRCODE=''23514''; END IF;\n ELSE key:=NEW.case_id; END IF;\n PERFORM finance_supply_assert_agreement(key);\n RETURN NULL;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":fal